)

// proto 是下游协议。三者共用同一条分发管线，只在解析请求与写回复时不同。
type proto string

const (
	protoAnthropic proto = "anthropic"
	protoChat      proto = "openai-chat"
	protoResponses proto = "openai-responses"
)

func (p proto) writeError(w http.ResponseWriter, status int, msg string) {
	if p == protoAnthropic {
		writeError(w, status, msg)
		return
	}
	openai.WriteError(w, status, msg)
}

func (p proto) newID() string {
	switch p {
	case protoChat:
		return openai.NewID("chatcmpl-")
	case protoResponses:
		return openai.NewID("resp_")
	}
	return openai.NewID("msg_")
}

// thinkingTagTokens 是 thinking 开启时加在 system 前的标签的 token 数。
const thinkingTagTokens = 24

// call 是一次下游请求在分发层里的状态。
type call struct {
	proto    proto
	req      anthropic.Request
	chat     openai.ChatOptions
	model    string // Kiro 模型 id
	thread   string // 会话线程键：粘号、钉 conversationId、钉 thinking
	budget   int
	lineage  []uint64
	prompt   *meter.Prompt
	key      *keys.Key // nil 是匿名（未配 key 或命中 config.api_keys）
	start    time.Time
	entry    usage.Entry // 最终记账
	recorded bool        // 成功时在写出结尾前已记账
}

// generate 是三个生成接口的公共入口。
func (s *Server) generate(p proto) apiHandler {
	return func(w http.ResponseWriter, r *http.Request, k *keys.Key) {
		c, err := s.prepare(r, p)
		if err != nil {
			p.writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		c.key = k
		if status, err := s.admit(w, c); err != nil {
			s.log.Info("request refused", "key", k.Name, "model", c.model, "err", err)
			p.writeError(w, status, err.Error())
			return
		}
		s.ensureCatalog()
		s.dispatch(w, r, c)
	}
}

// prepare 解析并整理请求，算出会话线程、thinking 预算与本地计量用的前缀形状。
func (s *Server) prepare(r *http.Request, p proto) (*call, error) {
	raw, err := io.ReadAll(http.MaxBytesReader(nil, r.Body, maxBody))
	if err != nil {
		return nil, fmt.Errorf("read body: %w", err)
	}
	c := &call{proto: p, start: time.Now()}
	switch p {
	case protoChat:
		c.req, c.chat, err = openai.FromChat(raw)
	case protoResponses:
		c.req, _, err = openai.FromResponses(raw)
	default:
		if err = json.Unmarshal(raw, &c.req); err != nil {
			err = fmt.Errorf("a request that isn't Messages JSON: %w", err)
		} else if len(c.req.Messages) == 0 {
			err = errors.New("messages: at least one message is required")
		}
	}
	if err != nil {
		return nil, err
	}
	normalize.Request(&c.req, s.norm)
	c.model = kiroModel(c.req.Model, s.cfg.ModelAliases, s.models.known)
	c.thread = threadKey(r, &c.req)
	c.lineage = lineage(&c.req)

	c.budget = kiro.ThinkingBudget(&c.req, c.model)
	if s.cfg.PinThinking && c.thread != "" {
		// 同一线程的 thinking 以首次为准：它写在首条消息前面，一变整段前缀就变
		if pinned, ok := s.think.get(c.thread); ok {
			c.budget = pinned
		}
		s.think.set(c.thread, c.budget)
	}

	extra := 0
	if c.budget > 0 {
		extra = thinkingTagTokens
	}
	// 前缀按整理后的请求算：这就是发给上游的内容。模型与 thinking 设置不同即不同缓存。
	c.prompt = meter.Analyze(&c.req, c.model+"|"+strconv.Itoa(c.budget), extra, s.cfg.CacheMode)
	return c, nil
}

// admit 做 key 的准入判断：模型白名单、周期预算、每分钟请求数。
func (s *Server) admit(w http.ResponseWriter, c *call) (int, error) {
	k := c.key
	if k == nil {
		return 0, nil
	}
	if !k.Allows(c.req.Model, c.model) {
		return http.StatusForbidden, fmt.Errorf("%w: %s", keys.ErrModel, c.req.Model)
	}
	now := time.Now()
	t := s.usage.Spend(k.ID, k.PeriodStart(now, time.Local))
	err := k.Check(now, keys.Spent{Requests: t.Requests, Credits: t.Credits, CostUSD: t.CostUSD}, time.Local)
	if err == nil {
		err = s.keys.Allow(k)
	}
	return admitStatus(w, err), err
}

func admitStatus(w http.ResponseWriter, err error) int {
	if err == nil {
		return 0
	}
	if le, ok := errors.AsType[*keys.LimitError](err); ok {
		if le.RetryAfter > 0 {
			w.Header().Set("Retry-After", strconv.Itoa(max(1, int(le.RetryAfter.Seconds()))))
		}
		if le.What == "rpm" {
			return http.StatusTooManyRequests
		}
		// 预算用完：402 让客户端别自动重试（429 会被当成短暂限流）
		return http.StatusPaymentRequired
	}
	if errors.Is(err, keys.ErrModel) {
		return http.StatusForbidden
	}
	return http.StatusUnauthorized
}

// threadKey 是会话键加首条前缀。客户端给的 session 在主线程与子 agent / 标题生成间共享，
// 它们的 system 与首条 user 不同，必须是不同的上游 conversation。
func threadKey(r *http.Request, req *anthropic.Request) string {
	msgs := normalize.PinMessages(req)
	clientKey := cmp.Or(req.PromptCacheKey, r.Header.Get("X-Claude-Code-Session-Id"), normalize.MetadataSession(req))
	base := sessionpin.Key(r.Header, clientKey, msgs)
	prefix := sessionpin.Key(nil, "", msgs)
	if strings.HasPrefix(base, "hdr:") && prefix != "" {
		return base + "|" + prefix
	}
	return base
}

// outcome 是一次上游尝试的结果。
type outcome struct {
	done    bool // 已向下游写出响应（成功或不可重试的失败）
	failure *kiro.Failure
}

func (s *Server) dispatch(w http.ResponseWriter, r *http.Request, c *call) {
	ctx := r.Context()
	c.entry = usage.Entry{Time: c.start, Model: c.model, Protocol: string(c.proto), Stream: c.req.Stream, Thread: shortKey(c.thread)}
	if c.key != nil {
		c.entry.Key, c.entry.KeyName = c.key.ID, c.key.Name
	}
	defer func() {
		if !c.recorded {
			c.entry.MS = time.Since(c.start).Milliseconds()
			s.usage.Record(c.entry)
		}
	}()
	fail := func(status int, msg string) {
		c.entry.Status, c.entry.Error = status, msg
		c.proto.writeError(w, status, msg)
	}

	var tried []string
	var last *kiro.Failure
	for range s.cfg.MaxAttempts {
		lease, err := s.pool.Acquire(c.thread, tried)
		if err != nil {
			if last != nil {
				fail(last.Status, last.Message)
				return
			}
			status := http.StatusServiceUnavailable
			if ue, ok := errors.AsType[*pool.UnavailableError](err); ok && !ue.RetryAt.IsZero() {
				status = http.StatusTooManyRequests
				w.Header().Set("Retry-After", strconv.Itoa(max(1, int(time.Until(ue.RetryAt).Seconds()))))
			}
			s.reqlog.add(requestRecord{Time: time.Now(), Protocol: string(c.proto), Key: c.entry.KeyName, Model: c.model,
				Stream: c.req.Stream, Thinking: c.budget, Thread: shortKey(c.thread), Status: status, Error: err.Error()})
			fail(status, err.Error())
			return
		}
		c.entry.Attempts++
		c.entry.Account, c.entry.Pinned = lease.ID, lease.Pinned
		out := s.attempt(ctx, w, lease, c)
		lease.Release()
		if out.done || ctx.Err() != nil {
			if ctx.Err() != nil && c.entry.Status == 0 {
				c.entry.Status, c.entry.Error = statusClientClosed, "client went away"
			}
			return
		}
		tried = append(tried, lease.ID)
		last = out.failure
	}
	if last == nil {
		last = &kiro.Failure{Status: http.StatusBadGateway, Message: "no attempt succeeded"}
	}
	fail(last.Status, last.Message)
}

// attempt 在一个号上试一次。在向下游写出任何字节之前失败都可以换号重试。
func (s *Server) attempt(ctx context.Context, w http.ResponseWriter, lease *pool.Lease, c *call) outcome {
	id := lease.ID
	rec := requestRecord{Time: time.Now(), Protocol: string(c.proto), Key: c.entry.KeyName, Account: id, Model: c.model,
		Stream: c.req.Stream, Thinking: c.budget, Pinned: lease.Pinned, Thread: shortKey(c.thread)}
	defer func() { rec.MS = time.Since(rec.Time).Milliseconds(); s.reqlog.add(rec) }()
	note := func(f kiro.Failure) {
		rec.Status, rec.Error = f.Status, f.Message
		c.entry.Status, c.entry.Error = f.Status, f.Message
	}
	gone := func() {
		rec.Status, rec.Error = statusClientClosed, "client went away"
		c.entry.Status, c.entry.Error = statusClientClosed, "client went away"
	}
	terminal := func(f kiro.Failure) outcome {
		note(f)
		c.proto.writeError(w, f.Status, f.Message)
		return outcome{done: true}
	}

	cred, err := s.pool.Cred(ctx, id, "")
	if err != nil {
		f := kiro.Failure{Status: http.StatusBadGateway, Message: "credentials: " + err.Error(), Class: kiro.ClassAuth}
		note(f)
		s.pool.Fail(id, f)
		return outcome{failure: &f}
	}

	convID := ""
	if s.cfg.ConversationMode == config.ConversationSession && c.thread != "" {
		// 前缀延续按 线程+号 判断：同一线程并发落在不同号上时互不干扰
		if prev, ok := s.lines.get(lineKey(c.thread, id)); ok && !continues(prev, c.lineage) {
			// 历史被改写（回退 / 压缩 / 编辑）：该号上的旧 conversation 已不是前缀
			s.conv.ForgetAccount(c.thread, id)
		}
		convID = s.conv.ID(c.thread, id)
	}
	rec.Conv = shortKey(convID)
	opts := kiro.BuildOptions{Model: c.model, ProfileArn: cred.ProfileArn, ConversationID: convID, ThinkingBudget: c.budget}
	payload, names, err := kiro.Build(&c.req, opts)
	if err != nil {
		return terminal(kiro.Failure{Status: http.StatusBadRequest, Message: "build request: " + err.Error()})
	}

	res, err := s.pool.Client().Generate(ctx, cred, payload)
	if err == nil && res.StatusCode == http.StatusForbidden {
		// token 被拒：刷新后在同一号上再试一次
		drain(res)
		if cred, err = s.pool.Cred(ctx, id, cred.AccessToken); err == nil {
			if cred.ProfileArn != opts.ProfileArn {
				opts.ProfileArn = cred.ProfileArn
				payload, _, _ = kiro.Build(&c.req, opts)
			}
			res, err = s.pool.Client().Generate(ctx, cred, payload)
		}
	}
	if err != nil {
		if ctx.Err() != nil {
			gone()
			return outcome{done: true}
		}
		f := kiro.Failure{Status: http.StatusBadGateway, Message: err.Error(), Class: kiro.ClassTransient}
		note(f)
		s.pool.Fail(id, f)
		return outcome{failure: &f}
	}
	defer drain(res)

	if res.StatusCode/100 != 2 {
		body, _ := io.ReadAll(io.LimitReader(res.Body, 1<<20))
		f := kiro.Classify(res.StatusCode, body)
		if !s.pool.Fail(id, f) {
			return terminal(f)
		}
		note(f)
		return outcome{failure: &f}
	}

	dec := kiro.NewDecoder(res.Body, c.budget > 0, s.models.window(c.model), names)
	first, err := dec.Next()
	if err == nil && first.Kind == kiro.EvError {
		f := kiro.ClassifyStream(first.Text)
		if !s.pool.Fail(id, f) {
			return terminal(f)
		}
		note(f)
		return outcome{failure: &f}
	}

	// 输入侧按本地 prompt cache 模拟拆分；缓存跟号走，与上游一致
	split := s.cache.Peek(id, c.prompt)
	input := turn.Usage{Input: split.Input, CacheRead: split.CacheRead, CacheWrite: split.CacheWrite}
	settle := func(u turn.Usage, k kiro.Usage) turn.Usage {
		u.CostUSD = s.pricer.Cost(c.model, u, split.CacheWrite1h)
		// 先记账再写结尾：下一个请求的预算判断要看到这一笔
		c.entry.Status, c.entry.Error = http.StatusOK, ""
		c.entry.Input, c.entry.CacheRead, c.entry.CacheWrite = u.Input, u.CacheRead, u.CacheWrite
		c.entry.Output, c.entry.Reasoning = u.Output, u.Reasoning
		c.entry.Credits, c.entry.CostUSD, c.entry.Context = u.Credits, u.CostUSD, k.Input
		c.entry.MS = time.Since(c.start).Milliseconds()
		s.usage.Record(c.entry)
		c.recorded = true
		return u
	}
	respID := c.proto.newID()

	var out reply
	if c.req.Stream {
		// 流式：从这里开始向下游输出，不再重试
		s.commit(c, id)
		w.Header().Set("X-Kiro-Account", id)
		out = pump(ctx, dec, first, s.streamSink(w, c, respID), input, settle)
	} else {
		// 非流式：整条收完才写下游，中途失败仍可换号
		col := &turn.Collector{}
		out = pump(ctx, dec, first, col, input, settle)
		switch {
		case out.failure != nil && ctx.Err() == nil:
			f := *out.failure
			if s.pool.Fail(id, f) {
				note(f)
				s.log.Warn("reply broke off, failing over", "account", id, "msg", f.Message)
				return outcome{failure: &f}
			}
			return terminal(f)
		case !out.ok:
			gone() // 下游走了，读失败不是号的错
			return outcome{done: true}
		}
		s.commit(c, id)
		col.Turn.ID, col.Turn.Model = respID, c.req.Model
		w.Header().Set("X-Kiro-Account", id)
		s.writeTurn(w, c, &col.Turn)
	}

	u := out.usage
	rec.Input, rec.Output, rec.CacheRead, rec.CacheWrite = u.Input, u.Output, u.CacheRead, u.CacheWrite
	rec.Credits, rec.CostUSD = u.Credits, u.CostUSD
	switch {
	case out.ok:
		s.cache.Commit(id, c.prompt)
		rec.Status, rec.OK = http.StatusOK, true
		s.pool.Success(id, kiro.Usage{Input: u.Input, Output: u.Output, CacheRead: u.CacheRead, CacheWrite: u.CacheWrite, Credits: u.Credits}, u.CostUSD)
	case out.failure != nil:
		// 流式中途失败：下游已收到 error 事件，这里记到号上（限流冷却 / 统计）
		note(*out.failure)
		s.pool.Fail(id, *out.failure)
	default:
		gone()
	}
	s.log.Info("generate",
		"proto", c.proto, "key", c.entry.KeyName, "account", id, "lease_pinned", lease.Pinned,
		"thread", shortKey(c.thread), "conv", shortKey(convID), "model", c.model, "stream", c.req.Stream, "thinking", c.budget,
		"input", u.Input, "output", u.Output, "cache_read", u.CacheRead, "cache_write", u.CacheWrite,
		"credits", u.Credits, "cost_usd", u.CostUSD, "ok", out.ok, "ms", time.Since(c.start).Milliseconds())
	return outcome{done: true}
}

func (s *Server) streamSink(w http.ResponseWriter, c *call, id string) turn.Sink {
	switch c.proto {
	case protoChat:
		return openai.NewChatStream(w, id, c.req.Model, c.start.Unix(), c.chat.IncludeUsage)
	case protoResponses:
		return openai.NewResponsesStream(w, id, c.req.Model, c.start.Unix())
	}
	return newAnthropicStream(w, id, c.req.Model)
}

func (s *Server) writeTurn(w http.ResponseWriter, c *call, t *turn.Turn) {
	switch c.proto {
	case protoChat:
		writeJSON(w, http.StatusOK, openai.ChatCompletion(t, c.start.Unix()))
	case protoResponses:
		writeJSON(w, http.StatusOK, openai.Response(t, c.start.Unix()))
	default:
		writeJSON(w, http.StatusOK, anthropicMessage(t))
	}
}

// commit 在确定由该号答复后记住：会话钉到这个号，并记下该号上的消息指纹。
func (s *Server) commit(c *call, id string) {
	if c.thread == "" {
		return
	}
	s.pool.Pin(c.thread, id)
	s.lines.set(lineKey(c.thread, id), c.lineage)
}

func lineKey(thread, account string) string { return thread + "\x00" + account }

func drain(res *http.Response) {
	_, _ = io.Copy(io.Discard, io.LimitReader(res.Body, 64<<10))
	res.Body.Close()
}

func shortKey(k string) string {
	if k == "" {
		return ""
	}
	sum := sha256.Sum256([]byte(k))
	return hex.EncodeToString(sum[:4])
}

// countTokens 按本地计量规则估 input tokens（与计费一致）。Kiro 没有对应接口。
func (s *Server) countTokens(w http.ResponseWriter, r *http.Request, _ *keys.Key) {
	raw, err := io.ReadAll(http.MaxBytesReader(nil, r.Body, maxBody))
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	var req anthropic.Request
	if err := json.Unmarshal(raw, &req); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	normalize.Request(&req, s.norm)
	writeJSON(w, http.StatusOK, map[string]int{"input_tokens": meter.Analyze(&req, "", 0, meter.ModeOff).Tokens})
}

// listModels 同时是 Anthropic 与 OpenAI 的模型列表形状。key 限定了模型时只列允许的。
func (s *Server) listModels(w http.ResponseWriter, r *http.Request, k *keys.Key) {
	if len(s.models.list()) == 0 {
		ctx, cancel := context.WithTimeout(r.Context(), 20*time.Second)
		s.refreshCatalog(ctx)
		cancel()
	}
	type model struct {
		Type        string `json:"type"`
		Object      string `json:"object"`
		ID          string `json:"id"`
		DisplayName string `json:"display_name"`
		CreatedAt   string `json:"created_at"`
		Created     int64  `json:"created"`
		OwnedBy     string `json:"owned_by"`
		Context     int    `json:"context_window,omitzero"`
		MaxOutput   int    `json:"max_output_tokens,omitzero"`
	}
	data := []model{}
	for _, m := range s.models.list() {
		if k != nil && !k.Allows(m.ID) {
			continue
		}
		data = append(data, model{Type: "model", Object: "model", ID: m.ID, DisplayName: m.Name,
			CreatedAt: "2025-01-01T00:00:00Z", Created: 1735689600, OwnedBy: "kiro", Context: m.Context, MaxOutput: m.Output})
	}
	if len(data) == 0 {
		// 不编造模型：客户端会把它当真列出来，然后请求必然失败
		writeError(w, http.StatusServiceUnavailable, "no model list: the pool is empty or no account could list models; add or fix an account (see /admin/accounts)")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"object": "list", "data": data, "has_more": false, "first_id": data[0].ID, "last_id": data[len(data)-1].ID})
}

// Kiro's subscriptions (kiro.dev) as an OpenCode provider plugin.
//
// An account is signed in the way the Kiro IDE signs in: Kiro's sign-in
// page (app.kiro.dev) offers Google, GitHub, AWS Builder ID and IAM
// Identity Center, and sends the browser back to one of the ports the IDE
// listens on. Google and GitHub come back with a code Kiro's auth service
// trades for tokens; Builder ID and Identity Center come back with where to
// sign in at AWS, which is then done with a client registered for it.
// kiro-cli's or the IDE's own sign-in can be used instead: it is read where
// they keep it each time, refreshed by kiro-cli first, and a token
// refreshed here is written back, so they go on with it. A Kiro API key
// (ksk_…) signs in too.
//
// Kiro has no API OpenCode speaks: the models are declared on Anthropic's
// Messages, and the fetch here sends each request whole to Kiro's own API
// (runtime.<region>.kiro.dev/generateAssistantResponse, the one kiro-cli
// talks to) as a conversation, and turns the AWS event stream it answers
// with back into Messages' events.
import { createServer } from "node:http"
import { createHash, randomBytes, randomUUID } from "node:crypto"
import { execFile } from "node:child_process"
import { existsSync, statSync } from "node:fs"
import { readFile, rename, writeFile } from "node:fs/promises"
import { homedir, hostname } from "node:os"
import { delimiter, join } from "node:path"

const ID = "kiro"
const MESSAGES = "@ai-sdk/anthropic"
const BASE = "https://runtime.us-east-1.kiro.dev" // what OpenCode is given; the fetch sends each request to the account's region

const PORTAL = "https://app.kiro.dev"
const AUTH_SERVICE = "https://prod.us-east-1.auth.desktop.kiro.dev"
const oidc = (region) => `https://oidc.${region}.amazonaws.com`
const runtime = (region) => `https://runtime.${region}.kiro.dev`
const management = (region) => `https://management.${region}.kiro.dev`
const refreshURL = (region) => `https://prod.${region}.auth.desktop.kiro.dev/refreshToken`
// the ports Kiro's sign-in page sends the browser back to, the IDE's
const CALLBACK_PORTS = [3128, 4649, 6588, 8008, 9091, 49153, 50153, 51153, 52153, 53153]
// what the IDE asks AWS for
const SCOPES = ["codewhisperer:completions", "codewhisperer:analysis", "codewhisperer:conversations",
  "codewhisperer:transformations", "codewhisperer:taskassist"]
// how the IDE names itself to Kiro's auth service, and when refreshing
const IDE_UA = "KiroIDE-1.1.70-" + createHash("sha256").update("magpie:" + hostname()).digest("hex")
const DESKTOP_UA = "Kiro-Desktop/0.2.13 (darwin; arm64)"
const SIGN_IN_TIMEOUT = 10 * 60 * 1000
// A Builder ID sign-in has no profile of its own, and Kiro won't list one
// for it (List-Available-Profiles is a 403, "AWS Builder ID is not supported
// for this operation"); the Kiro IDE and kiro-cli name this service profile
// for it instead, so its models, usage and chat are asked with it too.
const BUILDER_ID_START = "https://view.awsapps.com/start"
const BUILDER_ID_PROFILE = "arn:aws:codewhisperer:us-east-1:638616132270:profile/AAAACCCCXXXX"
const isBuilderID = (provider) => String(provider ?? "").toLowerCase() === "builderid"

const env = (k) => process.env[k] ?? ""
const home = () => env("HOME") || homedir()

// ---- where Kiro's own apps keep their sign-in -----------------------------------

function cliDB() {
  if (process.platform === "win32") return join(env("APPDATA") || join(home(), "AppData", "Roaming"), "kiro-cli", "data.sqlite3")
  if (process.platform === "darwin") return join(home(), "Library", "Application Support", "kiro-cli", "data.sqlite3")
  return join(home(), ".local", "share", "kiro-cli", "data.sqlite3")
}
const ideDir = () => join(home(), ".aws", "sso", "cache")

// kiroExecutable finds kiro-cli, which refreshes its own sign-in.
function kiroExecutable() {
  for (const d of env("PATH").split(delimiter)) {
    const p = join(d, process.platform === "win32" ? "kiro-cli.exe" : "kiro-cli")
    if (d && isFile(p)) return p
  }
  for (const p of [join(home(), ".local", "bin", "kiro-cli"), "/Applications/Kiro CLI.app/Contents/MacOS/kiro-cli",
    "/usr/local/bin/kiro-cli", "/opt/homebrew/bin/kiro-cli"])
    if (isFile(p)) return p
  return ""
}
function isFile(p) {
  try {
    return statSync(p).isFile()
  } catch {
    return false
  }
}

// openDB opens kiro-cli's SQLite database, with Bun's driver or Node's.
async function openDB(path, readonly) {
  try {
    const { Database } = await import("bun:sqlite")
    return new Database(path, readonly ? { readonly: true } : { readwrite: true })
  } catch (e) {
    if (typeof Bun !== "undefined") throw e
  }
  const { DatabaseSync } = await import("node:sqlite")
  return new DatabaseSync(path, { readOnly: readonly })
}

const time = (s) => {
  const t = Date.parse(s ?? "")
  return Number.isFinite(t) ? t : 0
}

// readCLI reads kiro-cli's sign-in: with Google or GitHub, with AWS (Builder
// ID, IAM Identity Center), or with a company's own identity provider.
async function readCLI() {
  const path = cliDB()
  if (!existsSync(path)) return null
  let db
  try {
    db = await openDB(path, true)
    const get = (key) => {
      const row = db.prepare("SELECT value FROM auth_kv WHERE key = ?").get(key)
      if (!row?.value) return null
      try {
        return JSON.parse(row.value)
      } catch {
        return null
      }
    }
    for (const kind of ["social", "odic", "external-idp"]) {
      const key = `kirocli:${kind}:token`
      const m = get(key)
      if (!m?.access_token) continue
      const c = { access: m.access_token, refresh: m.refresh_token ?? "", expires: time(m.expires_at), region: m.region || "us-east-1",
        profile: m.profile_arn ?? "", dbKey: key }
      if (kind === "social") c.method = "social"
      else if (kind === "odic") {
        c.method = "idc"
        // as kiro-cli tells them apart: Builder ID's start URL, or none
        c.builderID = !m.start_url || m.start_url === BUILDER_ID_START
        const reg = get("kirocli:odic:device-registration")
        if (reg) [c.clientId, c.clientSecret] = [reg.client_id ?? "", reg.client_secret ?? ""]
      } else {
        c.method = "external-idp"
        c.clientId = m.client_id ?? ""
        c.tokenURL = m.token_endpoint || (m.issuer_url ? m.issuer_url.replace(/\/$/, "") + "/v1/token" : "")
      }
      return c
    }
  } catch {
  } finally {
    db?.close()
  }
  return null
}

// readIDE reads the Kiro IDE's sign-in.
async function readIDE() {
  const path = join(ideDir(), "kiro-auth-token.json")
  let t
  try {
    t = JSON.parse(await readFile(path, "utf8"))
  } catch {
    return null
  }
  if (!t?.accessToken) return null
  const c = { access: t.accessToken, refresh: t.refreshToken ?? "", expires: time(t.expiresAt), region: t.region || "us-east-1",
    profile: t.profileArn ?? "", method: "idc", idePath: path, builderID: isBuilderID(t.provider) }
  if (t.clientIdHash) {
    try {
      const reg = JSON.parse(await readFile(join(ideDir(), t.clientIdHash + ".json"), "utf8"))
      ;[c.clientId, c.clientSecret] = [reg.clientId ?? "", reg.clientSecret ?? ""]
    } catch {}
  }
  if (String(t.authMethod).toLowerCase() === "social" || !c.clientId) c.method = "social"
  return c
}

// saveBack writes a refreshed token back where it was read from, so
// kiro-cli or the IDE goes on with it (a refresh may replace the refresh
// token).
async function saveBack(c) {
  const expires = new Date(c.expires).toISOString()
  if (c.dbKey) {
    let db
    try {
      db = await openDB(cliDB(), false)
      db.exec("PRAGMA busy_timeout = 3000")
      const row = db.prepare("SELECT value FROM auth_kv WHERE key = ?").get(c.dbKey)
      if (!row?.value) return
      const m = JSON.parse(row.value)
      Object.assign(m, { access_token: c.access, refresh_token: c.refresh, expires_at: expires })
      if (c.profile && c.method === "social") m.profile_arn = c.profile
      db.prepare("UPDATE auth_kv SET value = ? WHERE key = ?").run(JSON.stringify(m), c.dbKey)
    } catch {
    } finally {
      db?.close()
    }
  } else if (c.idePath) {
    try {
      const m = JSON.parse(await readFile(c.idePath, "utf8"))
      Object.assign(m, { accessToken: c.access, refreshToken: c.refresh, expiresAt: expires })
      await writeFile(c.idePath + ".magpie-tmp", JSON.stringify(m, null, 2), { mode: 0o600 })
      await rename(c.idePath + ".magpie-tmp", c.idePath)
    } catch {}
  }
