class KiroError extends Error {
  constructor(status, body) {
    let msg = ""
    try {
      msg = JSON.parse(body)?.message ?? ""
    } catch {}
    super(msg ? `Kiro: ${msg} (${status})` : `Kiro: ${STATUS_TEXT[status] ?? ""}`)
    this.status = status
