var armTimers = {};
function onAccountAction(btn){
  var act = btn.getAttribute('data-act');
  var id = btn.getAttribute('data-id');
  if (!act || !id) return;
  if (act === 'delete') {
    if (!btn.classList.contains('armed')) {
      btn.classList.add('armed');
      btn.textContent = '确认删除';
      clearTimeout(armTimers[id]);
      armTimers[id] = setTimeout(function(){ btn.classList.remove('armed'); btn.textContent = '删除'; }, 4000);
      return;
    }
    clearTimeout(armTimers[id]);
    btn.disabled = true;
    api('DELETE', '/admin/accounts/' + encodeURIComponent(id)).then(function(){
      toast('已删除 ' + id);
      return loadAccounts();
    }).catch(function(){ btn.disabled = false; });
    return;
  }
  var label = act === 'refresh' ? '刷新' : (act === 'enable' ? '启用' : '停用');
  btn.disabled = true;
  var old = btn.textContent;
  if (act === 'refresh') btn.textContent = '刷新中';
  api('POST', '/admin/accounts/' + encodeURIComponent(id) + '/' + act).then(function(v){
    toast(label + '完成：' + id);
    if (v && v.id) {
      for (var i = 0; i < state.accounts.length; i++) {
        if (state.accounts[i].id === v.id) { state.accounts[i] = v; break; }
      }
      renderAccounts();
    } else {
      loadAccounts().catch(ignore);
    }
  }).catch(function(){
    btn.disabled = false;
    btn.textContent = old;
  });
}

function afterAdd(d, what){
  var id = (d && d.id) || (d && d.account && d.account.id) || '';
  var msg = what + '成功' + (id ? '：' + id : '');
  if (d && d.warning) msg += '。额度拉取失败：' + d.warning;
  toast(msg, !!(d && d.warning));
  return loadAccounts();
}

